201	    private func beginRecording() {
202	        guard let engine else {
203	            _ = machine.handle(.abort)
204	            recorder.cancel()
205	            hud.flash(.error(engineHint ?? "Transcription engine not configured"), for: 2.5)
206	            return
207	        }
208	        guard PermissionsManager.microphoneAuthorized() else {
209	            _ = machine.handle(.abort)
210	            hud.flash(.error("Microphone permission needed"), for: 2.5)
211	            Task { _ = await PermissionsManager.requestMicrophoneAccess() }
212	            return
213	        }
214	        // Capture which app we're dictating into now (focus is stable during the
215	        // hold — the global hotkey doesn't steal it), to pick vocabulary later.
216	        let front = NSWorkspace.shared.frontmostApplication
217	        dictationContext = AppContext.classify(bundleID: front?.bundleIdentifier,
218	                                               appName: front?.localizedName)
219	        dictationPID = front?.processIdentifier
220	        do {
221	            // Streaming engines (Kyutai) open a session and feed audio live during
222	            // the hold; batch engines accumulate Int16 and transcribe on release.
223	            if let streaming = engine as? StreamingTranscriptionEngine {
224	                let session = try streaming.makeSession()
225	                // Don't paint live partials on screen while a secure field is
226	                // focused — a dictated password must not be shown/screen-captured.
227	                session.onPartial = { [weak self] text in
228	                    self?.hud.updateLiveText(isSecureInputActive() ? "" : text)
229	                }
